//! The `files` component credential (S11): the SMB password of `filesmb`.
//!
//! The password is GENERATED by the component installer (never typed by
//! the user, never in args, never in the receipt) and stored locally with
//! owner-only permissions. This module is the read side: it shows the
//! stored password so it can be pasted once into the phone's keychain,
//! and it can ask the component to rotate it.
//!
//! The secret lives in exactly one place: ~/.local/state/prim/files/.
//! State (not config) because it is machine-local and rotatable, and not
//! in ~/.local/share/prim/ where receipts live, because receipts are
//! metadata that other tools read.

use std::path::{Path, PathBuf};

/// Where the component stores the generated SMB password.
pub fn credential_path() -> PathBuf {
    let home = std::env::var("HOME").unwrap_or_else(|_| "/root".to_string());
    Path::new(&home)
        .join(".local/state/prim/files")
        .join("smb-password")
}

/// Read a password from an explicit path. None when the file is missing
/// or empty.
fn read_password_from(path: &Path) -> Option<String> {
    let raw = std::fs::read_to_string(path).ok()?;
    let pw = raw.trim().to_string();
    if pw.is_empty() {
        None
    } else {
        Some(pw)
    }
}

/// The stored password, if the component ever generated one.
pub fn read_password() -> Option<String> {
    read_password_from(&credential_path())
}

/// `prim files password [--rotate|--set]`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FilesCmd {
    /// Print the stored SMB password.
    Password,
    /// Generate a new one through the component.
    Rotate,
    /// Set a password the user chooses.
    Set,
}

/// The shortest secret prim accepts from the user.
const MIN_SECRET_LEN: usize = 12;

/// Parse the `files` subcommand. None on bad usage.
pub fn parse_args(args: &[String]) -> FilesCmd {
    match parse_files_cmd(args) {
        Ok(cmd) => cmd,
        Err(msg) => {
            eprintln!("{msg}");
            std::process::exit(2);
        }
    }
}

/// Parse the flags of `prim files password`. Err carries the usage
/// message; the two flags are exclusive and a rejected combination is
/// an error, never a silently resolved precedence.
fn parse_files_cmd(args: &[String]) -> Result<FilesCmd, String> {
    let mut rotate = false;
    let mut set = false;
    for a in args {
        match a.as_str() {
            "password" => {}
            "--rotate" => rotate = true,
            "--set" => set = true,
            other => {
                return Err(format!(
                    "[prim] uso: prim files password [--rotate|--set] (recibido: {other})"
                ));
            }
        }
    }
    if set && rotate {
        return Err(
            "[prim] uso: prim files password [--rotate|--set] (--rotate y --set no se combinan)"
                .to_string(),
        );
    }
    Ok(if set {
        FilesCmd::Set
    } else if rotate {
        FilesCmd::Rotate
    } else {
        FilesCmd::Password
    })
}

/// `prim files password` — print the stored credential so it can be
/// pasted into the phone. The secret goes to stdout, not to a receipt.
pub fn print_password() -> bool {
    match read_password() {
        Some(pw) => {
            println!("[prim] clave SMB de filesmb:");
            println!("{pw}");
            println!(
                "[prim] guardada en {} (solo el owner puede leerla).",
                credential_path().display()
            );
            true
        }
        None => {
            eprintln!(
                "[prim] no hay clave SMB guardada en {}.",
                credential_path().display()
            );
            eprintln!("[prim] generala con: prim files password --rotate");
            false
        }
    }
}

/// `prim files password --rotate` — generate a new one through the
/// component (it owns smbpasswd and the passdb). Nothing is written
/// here: the component is the only writer of the secret.
pub fn rotate_password() -> bool {
    eprintln!("[prim] generando una clave SMB nueva via el componente files...");
    crate::run_component("files/install.sh", &["rotate-password"])
}

/// `prim files password --set` — the user CHOOSES the password. It is
/// read from the terminal without echo (or from stdin when piped) and
/// applied straight from prim: prim owns its state dir and calls
/// smbpasswd. The secret never travels in argv, env or the receipt.
pub fn set_password() -> bool {
    let user = match share_user() {
        Ok(u) => u,
        Err(e) => {
            eprintln!("[prim] {e}");
            return false;
        }
    };
    let first = match read_secret(&format!("Nueva clave SMB para {user}: ")) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("[prim] no se pudo leer la clave: {e}");
            return false;
        }
    };
    let second = match read_secret("Repeti la clave: ") {
        Ok(v) => v,
        Err(e) => {
            eprintln!("[prim] no se pudo leer la confirmacion: {e}");
            return false;
        }
    };
    let secret = match validate_secret(&first, &second) {
        Ok(s) => s,
        Err(m) => {
            eprintln!("[prim] {m}");
            return false;
        }
    };
    match apply_password(&user, &secret) {
        Ok(()) => {
            if let Err(e) = store_password(&secret) {
                // The passdb holds the new secret but the local copy does
                // not: `prim files password` would print a stale one, so
                // the command fails instead of claiming success.
                eprintln!("[prim] la clave se aplico pero no se pudo guardar: {e}");
                return false;
            }
            println!("[prim] clave SMB de {user} actualizada.");
            true
        }
        Err(e) => {
            eprintln!("[prim] no se pudo aplicar la clave: {e}");
            false
        }
    }
}

/// Validate the two entries of a user-chosen secret. Ok carries the
/// secret to apply; Err carries the message to show.
fn validate_secret(first: &str, second: &str) -> Result<String, String> {
    if first != second {
        return Err("las claves no coinciden; no se cambio nada.".to_string());
    }
    if first.chars().count() < MIN_SECRET_LEN {
        return Err(format!(
            "la clave es demasiado corta (minimo {MIN_SECRET_LEN} caracteres)."
        ));
    }
    Ok(first.to_string())
}

/// The SMB login recorded by the component (the user may replace it).
/// The receipt is the only source of truth: a missing or unreadable
/// field is an error, never a silent default, because the password
/// would be applied to the wrong Samba account.
fn share_user() -> Result<String, String> {
    let path = std::env::var("HOME")
        .map(|h| format!("{h}/.local/share/prim/files.receipt.json"))
        .unwrap_or_default();
    let text = std::fs::read_to_string(&path)
        .map_err(|e| format!("no se pudo leer el receipt del componente files: {e}"))?;
    text.lines()
        .find_map(|l| {
            let rest = l.trim().strip_prefix("\"share_user\"")?;
            let rest = rest.trim_start().strip_prefix(':')?.trim_start();
            let value = rest.strip_prefix('"')?;
            Some(value.split('"').next().unwrap_or("").to_string())
        })
        .filter(|v| !v.is_empty())
        .ok_or_else(|| {
            "el receipt del componente files no declara share_user; repara con: prim install files"
                .to_string()
        })
}

/// Apply the password to the Samba passdb. The secret goes through
/// stdin only, never as an argument.
fn apply_password(user: &str, password: &str) -> std::io::Result<()> {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let mut child = Command::new("sudo")
        .arg("smbpasswd")
        .arg("-a")
        .arg("-s")
        .arg(user)
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()?;
    {
        let mut stdin = child
            .stdin
            .take()
            .ok_or_else(|| std::io::Error::other("no stdin"))?;
        writeln!(stdin, "{password}")?;
        writeln!(stdin, "{password}")?;
    }
    let out = child.wait_with_output()?;
    if out.status.success() {
        Ok(())
    } else {
        let msg = String::from_utf8_lossy(&out.stderr).trim().to_string();
        Err(std::io::Error::other(if msg.is_empty() {
            "smbpasswd fallo".to_string()
        } else {
            msg
        }))
    }
}

/// Store the credential in prim's private state (owner only).
fn store_password(password: &str) -> std::io::Result<()> {
    let path = credential_path();
    let dir = path
        .parent()
        .ok_or_else(|| std::io::Error::other("ruta de credencial invalida"))?;
    std::fs::create_dir_all(dir)?;
    std::fs::write(&path, format!("{password}\n"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600))?;
    }
    Ok(())
}

/// Read a secret from the terminal with echo off. Falls back to stdin
/// (two lines) when there is no terminal, so it also works piped.
fn read_secret(prompt: &str) -> std::io::Result<String> {
    use std::io::{BufRead, BufReader, Write};
    let tty = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open("/dev/tty");
    match tty {
        Ok(tty) => {
            print!("{prompt}");
            std::io::stdout().flush().ok();
            // stty reads the terminal attributes from its STDIN, so it
            // must get the tty itself: with an inherited (piped) stdin
            // the echo would stay on and the secret would be shown.
            set_echo(&tty, false);
            let mut line = String::new();
            let read = BufReader::new(&tty).read_line(&mut line);
            // Restore the echo on every path, including the error one.
            set_echo(&tty, true);
            let n = read?;
            println!();
            if n == 0 {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "entrada vacia",
                ));
            }
            Ok(line.trim().to_string())
        }
        Err(_) => {
            let mut line = String::new();
            let n = std::io::stdin().lock().read_line(&mut line)?;
            if n == 0 {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "entrada vacia",
                ));
            }
            Ok(line.trim().to_string())
        }
    }
}

/// Turn the terminal echo on or off. The tty handle is stty's stdin:
/// stty acts on the terminal it reads from.
fn set_echo(tty: &std::fs::File, on: bool) {
    let arg = if on { "echo" } else { "-echo" };
    let Ok(fd) = tty.try_clone() else { return };
    let _ = std::process::Command::new("stty")
        .arg(arg)
        .stdin(std::process::Stdio::from(fd))
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn credential_path_is_private_state_under_home() {
        let s = credential_path().to_string_lossy().to_string();
        assert!(s.ends_with(".local/state/prim/files/smb-password"), "{s}");
        assert!(!s.contains("/share/"), "{s}");
    }

    #[test]
    fn missing_file_reads_as_none() {
        let dir = std::env::temp_dir().join("prim-files-test-missing");
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(read_password_from(&dir.join("nope")), None);
    }

    #[test]
    fn password_is_read_and_trimmed() {
        let dir = std::env::temp_dir().join("prim-files-test-read");
        std::fs::create_dir_all(&dir).unwrap();
        let f = dir.join("smb-password");
        std::fs::write(&f, "  abc123XYZ  \n").unwrap();
        assert_eq!(read_password_from(&f).as_deref(), Some("abc123XYZ"));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn empty_file_reads_as_none() {
        let dir = std::env::temp_dir().join("prim-files-test-empty");
        std::fs::create_dir_all(&dir).unwrap();
        let f = dir.join("smb-password");
        std::fs::write(&f, "   \n").unwrap();
        assert_eq!(read_password_from(&f), None);
        let _ = std::fs::remove_dir_all(&dir);
    }

    const PARSE_SCENARIOS: &[(&[&str], Option<FilesCmd>)] = &[
        (&["password"], Some(FilesCmd::Password)),
        (&["password", "--rotate"], Some(FilesCmd::Rotate)),
        (&["password", "--set"], Some(FilesCmd::Set)),
        // The two flags are exclusive: a rejected combination is an
        // error, never a silently resolved precedence.
        (&["password", "--rotate", "--set"], None),
        (&["password", "--bogus"], None),
    ];

    #[test]
    fn parse_files_cmd_follows_the_scenarios() {
        for (args, expected) in PARSE_SCENARIOS {
            let owned: Vec<String> = args.iter().map(|s| s.to_string()).collect();
            assert_eq!(parse_files_cmd(&owned).ok(), expected.clone(), "{args:?}");
        }
    }

    const SECRET_SCENARIOS: &[(&str, &str, bool)] = &[
        ("abcdefghijkl", "abcdefghijkl", true),
        // Mismatched entries.
        ("abcdefghijkl", "abcdefghijkm", false),
        // One character below the minimum.
        ("abcdefghijk", "abcdefghijk", false),
    ];

    #[test]
    fn validate_secret_follows_the_scenarios() {
        for (first, second, ok) in SECRET_SCENARIOS {
            assert_eq!(
                validate_secret(first, second).is_ok(),
                *ok,
                "{first:?}/{second:?}"
            );
        }
    }
}
